import sys

def print_memory_contents(text):
    with open("memory.txt", "r") as file:
        for line in file:
            if line.startswith("#"):
                print(line)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python print_memory_contents.py <text>\n")
        sys.exit(1)

    text = sys.argv[1]
    print_memory_contents(text)
